import React from 'react';

import { XYChartBottomAxisArea } from './components/axes/XYChartBottomAxisArea.js';
import { AREAS } from './constants/xy-chart-grid-areas.js';
import { XYChartAxisBorder } from './layout/XYChartAxisBorder.js';
import { XYChartLayout } from './layout/XYChartLayout.js';
import { XYChartProviders } from './providers/XYChartProviders.js';
import { ChartGrid } from '../core/components/chart-grid/ChartGridRoot.js';

const gridTemplateAreas = `
  "plot"
  "${AREAS.bottomAxis}"
`;

const gridTemplateColumns = 'minmax(60%, 1fr)';
const gridTemplateRows = 'minmax(60%, 1fr) minmax(0, auto)';

export const XYChart = ({ height }: { height?: string }) => {
  return (
    <ChartGrid
      width="100%"
      height={height}
      gridTemplateAreas={gridTemplateAreas}
      gridTemplateColumns={gridTemplateColumns}
      gridTemplateRows={gridTemplateRows}
    >
      <XYChartProviders>
        <XYChartBottomAxisArea />
        <ChartGrid.PlotArea>
          <XYChartAxisBorder />
          <XYChartLayout />
          {/*TODO APPDEV-8127 will fix these lines*/}
          {/*<GridZeroLineX />*/}
          {/*<GridZeroLineY />*/}
        </ChartGrid.PlotArea>
      </XYChartProviders>
    </ChartGrid>
  );
};

XYChart['displayName'] = 'XYChart';
